alter table public.dm_messages add column if not exists reply_to bigint references public.dm_messages(id) on delete set null;
create index if not exists dm_messages_reply_to_idx on public.dm_messages(reply_to) where reply_to is not null;
create table if not exists public.dm_message_reactions (id bigint generated by default as identity primary key,message_id bigint not null references public.dm_messages(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,emoji text not null check (emoji in ('👍','❤️','😂','😭','🔥','💀','👏','🥰')),created_at timestamptz not null default now(),constraint dm_message_reactions_unique unique(message_id,user_id,emoji));
create index if not exists dm_message_reactions_message_idx on public.dm_message_reactions(message_id);
alter table public.dm_message_reactions enable row level security;
grant select,insert,delete on public.dm_message_reactions to authenticated;
drop policy if exists "DM members can view reactions" on public.dm_message_reactions;
create policy "DM members can view reactions" on public.dm_message_reactions for select to authenticated using(exists(select 1 from public.dm_messages m join public.dm_conversations c on c.id=m.conversation_id where m.id=dm_message_reactions.message_id and ((select auth.uid())=c.user_one or (select auth.uid())=c.user_two)));
drop policy if exists "DM members can add their own reactions" on public.dm_message_reactions;
create policy "DM members can add their own reactions" on public.dm_message_reactions for insert to authenticated with check(user_id=(select auth.uid()) and exists(select 1 from public.dm_messages m join public.dm_conversations c on c.id=m.conversation_id where m.id=dm_message_reactions.message_id and ((select auth.uid())=c.user_one or (select auth.uid())=c.user_two)));
drop policy if exists "Users can remove their own DM reactions" on public.dm_message_reactions;
create policy "Users can remove their own DM reactions" on public.dm_message_reactions for delete to authenticated using(user_id=(select auth.uid()) and exists(select 1 from public.dm_messages m join public.dm_conversations c on c.id=m.conversation_id where m.id=dm_message_reactions.message_id and ((select auth.uid())=c.user_one or (select auth.uid())=c.user_two)));
do $$ begin if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='dm_message_reactions') then alter publication supabase_realtime add table public.dm_message_reactions; end if; end $$;